-- BANKING DATA CLEANING PROJECT
DROP DATABASE IF EXISTS real_projects;
CREATE DATABASE real_projects;
USE real_projects;

-- Raw customer table.
CREATE TABLE customer (
    customer_id VARCHAR(30),
    first_name VARCHAR(100),
    last_name VARCHAR(100),
    gender VARCHAR(30),
    date_of_birth VARCHAR(30),
    phone VARCHAR(50),
    email VARCHAR(150),
    city VARCHAR(100),
    state VARCHAR(100),
    customer_tier VARCHAR(50),
    registration_date VARCHAR(30),
    bvn VARCHAR(30)
);

-- Raw bank account table.
CREATE TABLE bank_account_details (
    account_id VARCHAR(30),
    customer_id VARCHAR(30),
    account_number VARCHAR(40),
    account_type VARCHAR(50),
    account_status VARCHAR(50),
    date_opened VARCHAR(30),
    current_balance VARCHAR(50),
    interest_rate VARCHAR(30),
    overdraft_limit VARCHAR(50),
    branch VARCHAR(100),
    last_transaction_date VARCHAR(30)
);



-- Quick checks before cleaning
SELECT COUNT(*) AS customer_rows FROM customer;
SELECT COUNT(*) AS account_rows FROM bank_account_details;
SELECT * FROM customer LIMIT 10;
SELECT * FROM bank_account_details LIMIT 10;
